function syncCatalog() {
  const canonical = catalog();
  for (const item of canonical) {
    const existing = db.services.find((s) => s.id === item.id);
    if (!existing) db.services.push({ ...item, active: true, createdAt: now() });
    else Object.assign(existing, { en: item.en, icon: item.icon, photo: item.photo || null, art: item.art || null, group: item.group, blurbBn: item.blurbBn, blurbEn: item.blurbEn, active: existing.active !== false });
  }
  for (const service of db.services) { if (!service.en) service.en = service.bn; }
}
